   var N=Arr.shift()-0;
   if(N==0)break;
   var str=Arr.shift();
   var AB=[];
   for(var i=0;i<N;i++){
      var ab=(Arr.shift()).split(" ").map(Number);
      AB.push(ab);
   }
   AB.reverse();
   var s=str.split("");
   for(var i=0;i<N;i++){
      var ab=AB[i];
      var plus=ab[1]-ab[0];
      var m1=s[ab[0]-1];
